package com.crm.invoice.service;
import com.crm.invoice.entity.*;import com.crm.invoice.repository.*;import com.crm.invoice.client.InvoiceSourceClient;import com.crm.invoice.dto.InvoiceRequest;import org.springframework.stereotype.Service;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.data.domain.*;import jakarta.validation.constraints.*;import java.util.*;import java.time.LocalDate;import java.math.BigDecimal;
@Service public class InvoiceReconciliationService {private final InvoiceReconciliationRepository jobs;private final InvoiceFeeClaimRepository claims;private final InvoiceRepository invoices;private final IInvoiceService service;private final InvoiceSourceClient source;private final TransactionTemplate writes;public InvoiceReconciliationService(InvoiceReconciliationRepository j,InvoiceFeeClaimRepository c,InvoiceRepository i,IInvoiceService s,InvoiceSourceClient r,PlatformTransactionManager tx){jobs=j;claims=c;invoices=i;service=s;source=r;writes=new TransactionTemplate(tx);}
 public record Input(@NotBlank @Size(min=36,max=36) String requestId,@NotBlank String customerId,@NotBlank @Pattern(regexp="[A-Z]{3}") String currency,@NotNull @Size(min=1,max=25) List<@NotBlank String> feeIds,@NotNull LocalDate issueDate,@NotNull LocalDate dueDate,@PositiveOrZero @Digits(integer=10,fraction=2) BigDecimal tax){}
 public record Job(String id,String customerId,String currency,List<String> feeIds,LocalDate issueDate,LocalDate dueDate,String tax,String state,String invoiceId,Integer errorStatus,String outcome){}
 public record Eligible(InvoiceSourceClient.Fee fee,String state,String jobId,String invoiceId){}
 public record CandidatePage(List<Eligible> content,int number,int totalPages,long totalElements){}
 public CandidatePage candidates(String customer,String currency,int page,String bearer){InvoiceWorkAccess.admin();var response=source.list(customer,currency,page,bearer);var ids=response.content().stream().map(f->InvoiceWorkAccess.id(f.id())).toList();Map<Long,InvoiceFeeClaim> current=new HashMap<>();if(!ids.isEmpty())claims.findByFeeIdIn(ids).forEach(c->current.put(c.getFeeId(),c));List<Eligible> result=new ArrayList<>();for(var f:response.content()){var claim=current.get(Long.parseLong(f.id()));var job=claim==null||claim.getJobId()==null?null:jobs.findById(claim.getJobId()).orElseThrow(InvoiceWorkAccess::conflict);result.add(new Eligible(f,job==null?"NON_RECONCILED":job.getState(),job==null?null:job.getId(),claim==null||claim.getInvoiceId()==null?null:claim.getInvoiceId().toString()));}return new CandidatePage(result,page,response.totalPages(),response.totalElements());}
 public Page<Job> list(int page){InvoiceWorkAccess.admin();if(page<0)throw new IllegalArgumentException("Invalid page");return jobs.findAll(PageRequest.of(page,20,Sort.by("createdAt").descending())).map(this::view);}
 public Job execute(Input input,String bearer){long actor=InvoiceWorkAccess.admin();InvoiceWorkAccess.valid(input);InvoiceWorkAccess.uuid(input.requestId());InvoiceWorkAccess.id(input.customerId());if(input.issueDate().getYear()<1000||input.dueDate().getYear()>9999||input.dueDate().isBefore(input.issueDate()))throw new IllegalArgumentException("Invalid invoice dates");var selected=input.feeIds().stream().map(InvoiceWorkAccess::id).sorted().toList();if(new HashSet<>(selected).size()!=selected.size())throw new IllegalArgumentException("Duplicate selected fee");String signature=selected.stream().map(Object::toString).collect(java.util.stream.Collectors.joining(","));
  Job ready=writes.execute(tx->{var old=jobs.lock(input.requestId());if(old.isPresent()){var j=old.get();if(!same(j,input,signature)||j.getState().equals("CANCELLED"))throw InvoiceWorkAccess.conflict();if(j.getState().equals("RECONCILED"))return view(j);j.setState("IN_PROGRESS");j.setErrorStatus(null);j.setOutcome(null);}else{var j=new InvoiceReconciliation();j.setId(input.requestId());j.setCustomerId(input.customerId());j.setCurrency(input.currency());j.setFeeIds(signature);j.setIssueDate(input.issueDate());j.setDueDate(input.dueDate());j.setTax(input.tax());j.setCreatedBy(actor);jobs.saveAndFlush(j);}for(long id:selected){var claim=claims.lock(id).orElseGet(()->{var c=new InvoiceFeeClaim();c.setFeeId(id);return c;});if(claim.getInvoiceId()!=null||claim.getJobId()!=null&&!claim.getJobId().equals(input.requestId()))throw InvoiceWorkAccess.conflict();claim.setJobId(input.requestId());claims.saveAndFlush(claim);}return view(jobs.findById(input.requestId()).orElseThrow(InvoiceWorkAccess::missing));});
  if(ready.state().equals("RECONCILED"))return ready;
  try{source.customer(input.customerId(),bearer);List<InvoiceSourceClient.Fee> fees=new ArrayList<>();BigDecimal subtotal=BigDecimal.ZERO;for(long id:selected){var f=source.get(id,bearer);if(!f.id().equals(Long.toString(id))||!f.customerId().equals(input.customerId())||!f.currency().equals(input.currency()))throw InvoiceWorkAccess.conflict();fees.add(f);subtotal=subtotal.add(new BigDecimal(f.amount()));}FinancialValidation.calculated(subtotal.add(input.tax()==null?BigDecimal.ZERO:input.tax()));final BigDecimal total=subtotal;
   return writes.execute(tx->{var j=jobs.lock(input.requestId()).orElseThrow(InvoiceWorkAccess::missing);if(j.getState().equals("RECONCILED"))return view(j);if(j.getState().equals("CANCELLED"))throw InvoiceWorkAccess.conflict();for(long id:selected){var c=claims.lock(id).orElseThrow(InvoiceWorkAccess::conflict);if(!j.getId().equals(c.getJobId())||c.getInvoiceId()!=null)throw InvoiceWorkAccess.conflict();}var request=new InvoiceRequest();request.setCustomerId(j.getCustomerId());request.setCurrency(j.getCurrency());request.setIssueDate(j.getIssueDate());request.setDueDate(j.getDueDate());request.setSubtotal(total);request.setTax(j.getTax());request.setStatus("DRAFT");request.setNotes("Prepared from immutable fee sources; no automatic issue");var created=service.createInvoice(request);var invoice=invoices.findById(created.getId()).orElseThrow(InvoiceWorkAccess::missing);invoice.setReconciliationId(j.getId());for(var f:fees){var line=new InvoiceLine();line.setInvoiceId(invoice.getId());line.setDescription(f.serviceName());line.setQuantity(new BigDecimal(f.hours()));line.setUnitPrice(new BigDecimal(f.rate()));line.setLineTotal(new BigDecimal(f.amount()));invoice.getLines().add(line);}invoices.saveAndFlush(invoice);for(int n=0;n<fees.size();n++){var claim=claims.lock(Long.parseLong(fees.get(n).id())).orElseThrow(InvoiceWorkAccess::conflict);claim.setInvoiceId(invoice.getId());claim.setLineId(invoice.getLines().get(n).getId());}j.setInvoiceId(invoice.getId());j.setState("RECONCILED");j.setErrorStatus(null);j.setOutcome(null);return view(j);});
  }catch(RuntimeException failure){int status=failure instanceof org.springframework.web.server.ResponseStatusException e?e.getStatusCode().value():failure instanceof IllegalArgumentException?400:failure instanceof org.springframework.dao.DataIntegrityViolationException?409:503;return writes.execute(tx->{var j=jobs.lock(input.requestId()).orElseThrow(InvoiceWorkAccess::missing);if(!j.getState().equals("RECONCILED")&&!j.getState().equals("CANCELLED")){j.setState("NEEDS_ATTENTION");j.setErrorStatus(status);j.setOutcome("Operation incomplete; retry or release the unconfirmed selection");}return view(j);});}
 }
 public Job retry(String id,String bearer){InvoiceWorkAccess.admin();var j=jobs.findById(id).orElseThrow(InvoiceWorkAccess::missing);return execute(new Input(j.getId(),j.getCustomerId(),j.getCurrency(),Arrays.asList(j.getFeeIds().split(",")),j.getIssueDate(),j.getDueDate(),j.getTax()),bearer);}
 public Job abandon(String id,String reason){InvoiceWorkAccess.admin();if(reason==null||reason.isBlank()||reason.length()>500)throw new IllegalArgumentException("Release reason required");return writes.execute(tx->{var j=jobs.lock(id).orElseThrow(InvoiceWorkAccess::missing);if(j.getInvoiceId()!=null||j.getState().equals("RECONCILED"))throw InvoiceWorkAccess.conflict();for(String fee:j.getFeeIds().split(",")){var claim=claims.lock(Long.parseLong(fee)).orElseThrow(InvoiceWorkAccess::conflict);if(j.getId().equals(claim.getJobId())&&claim.getInvoiceId()==null)claim.setJobId(null);}j.setState("CANCELLED");j.setOutcome(reason.trim());return view(j);});}
 private boolean same(InvoiceReconciliation j,Input i,String ids){return j.getCustomerId().equals(i.customerId())&&j.getCurrency().equals(i.currency())&&j.getFeeIds().equals(ids)&&j.getIssueDate().equals(i.issueDate())&&j.getDueDate().equals(i.dueDate())&&(j.getTax()==null?i.tax()==null:i.tax()!=null&&j.getTax().compareTo(i.tax())==0);}
 private Job view(InvoiceReconciliation j){return new Job(j.getId(),j.getCustomerId(),j.getCurrency(),Arrays.asList(j.getFeeIds().split(",")),j.getIssueDate(),j.getDueDate(),j.getTax()==null?null:j.getTax().toPlainString(),j.getState(),j.getInvoiceId()==null?null:j.getInvoiceId().toString(),j.getErrorStatus(),j.getOutcome());}
}
